// Picks the cheapest model on your list that is for sale right now.
const s = $('Settings').first().json;
const res = $input.first().json;
if (res.statusCode !== 200) {
  throw new Error('The MartLLM price list answered ' + res.statusCode + ': ' + (res.body?.error?.message || 'no message'));
}
const wanted = String(s.allowed_models || '').split(/[\n,]+/).map((x) => x.trim()).filter(Boolean);
if (!wanted.length) throw new Error('Settings: allowed_models is empty. List the model ids you trust for this job.');

const byId = new Map((res.body?.models || []).map((m) => [m.id, m]));
// Same rule as MartLLM's own best-price pick: price per 1M tokens, output counted three times.
const rank = (m) => m.input_per_m + 3 * m.output_per_m;
const forSale = wanted
  .map((id) => byId.get(id))
  .filter((m) => m && typeof m.input_per_m === 'number' && typeof m.output_per_m === 'number')
  .sort((a, b) => rank(a) - rank(b));
if (!forSale.length) {
  throw new Error('None of your models is for sale right now: ' + wanted.join(', ') + '. Check the ids at martllm.com/models.');
}
const best = forSale[0];
// Tried in this order only when nobody can serve the model before it. At most 5 models in one request.
const backups = forSale.slice(1, 5).map((m) => m.id);
const request = {
  model: best.id,
  max_tokens: Number(s.max_output_tokens) || 600,
  messages: [{ role: 'user', content: String(s.prompt || '') }],
  metadata: { template: 'cheapest-model-router' },
};
if (backups.length) request.models = backups;
if (s.instructions) request.messages.unshift({ role: 'system', content: String(s.instructions) });
return [{ json: {
  api_base: s.api_base,
  request,
  model: best.id,
  backup_models: backups,
  listed_input_per_m: best.input_per_m,
  listed_output_per_m: best.output_per_m,
  prices_read_at: res.body.updated_at,
  not_for_sale_now: wanted.filter((id) => !byId.has(id)),
} }];

// Reads the answer and what MartLLM billed for it.
const r = $json;
const b = r.body || {};
const u = b.usage || {};
const picked = $('Pick the cheapest model').first().json;
const cost = typeof u.cost_usd === 'number' ? u.cost_usd : Number(r.headers?.['x-uberllm-cost-usd']);
return { json: {
  answer: b.choices?.[0]?.message?.content ?? '',
  model: b.model || picked.model,
  cost_usd: Number.isFinite(cost) ? cost : null,
  input_tokens: u.prompt_tokens ?? null,
  output_tokens: u.completion_tokens ?? null,
  listed_input_per_m: picked.listed_input_per_m,
  listed_output_per_m: picked.listed_output_per_m,
  request_id: r.headers?.['x-request-id'] || b.id || '',
  time: new Date().toISOString(),
} };
